import{_ as t,o as s,c as a,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/reportdesigner/report-neu-und-veraendern-8.png",o="/bilder/reportdesigner/report-neu-und-veraendern-9.png",d="/bilder/reportdesigner/report-neu-und-veraendern-10.png",p="/bilder/reportdesigner/report-neu-und-veraendern-11.png",u="/bilder/reportdesigner/report-neu-und-veraendern-12.png",k=JSON.parse('{"title":"Einen vorhandenen Report anpassen","description":"","frontmatter":{"title":"Einen vorhandenen Report anpassen","source_pageid":1568,"source_revision":6680},"headers":[],"relativePath":"reporting/reportdesigner/einen-vorhandenen-report-anpassen.md","filePath":"reporting/reportdesigner/einen-vorhandenen-report-anpassen.md"}'),g={name:"reporting/reportdesigner/einen-vorhandenen-report-anpassen.md"};function h(c,i,f,b,m,_){return s(),a("div",null,[...i[0]||(i[0]=[r('<h1 id="einen-vorhandenen-report-anpassen" tabindex="-1">Einen vorhandenen Report anpassen <a class="header-anchor" href="#einen-vorhandenen-report-anpassen" aria-label="Permalink to &quot;Einen vorhandenen Report anpassen&quot;">​</a></h1><p>Nutzen Sie einen vorhandenen Report als Ausgangspunkt. Am Beispiel einer Schulbescheinigung ändern Sie Schrift, Positionen und ausgegebene Datenfelder.</p><p>Reports müssen nicht immer komplett neu erstellt werden. Auf der Webseite <strong>Schulverwaltungssoftware des MSB</strong> stehen bereits umfangreiche Reportsammlungen zur Verfügung. Oft ist es sinnvoll, zunächst zu prüfen, ob ein benötigter Report bereits existiert. Gefundene Reports lassen sich anschließend an die eigenen Bedürfnisse anpassen.</p><h2 id="_1-beispiel-schulbescheinigung-anpassen" tabindex="-1">1. Beispiel Schulbescheinigung anpassen <a class="header-anchor" href="#_1-beispiel-schulbescheinigung-anpassen" aria-label="Permalink to &quot;1. Beispiel Schulbescheinigung anpassen&quot;">​</a></h2><p><a href="/bilder/reportdesigner/report-neu-und-veraendern-8.png"><img src="'+l+'" alt="Eine Schulbescheinigung, die angepasst werden soll." loading="lazy"></a></p><p><em>Eine Schulbescheinigung, die angepasst werden soll.</em></p><p>Im folgenden Beispiel wird eine Schulbescheinigung aus einer Reportsammlung angepasst. Der Ausgangsreport könnte wie rechts dargestellt aussehen.</p><p>Es sollen folgende Veränderungen vorgenommen werden:</p><ul><li>Schriftart <strong>Arial</strong> → <strong>Calibri</strong></li><li>Datenfelder nicht mehr kursiv</li><li><strong>PLZ</strong> soll etwas nach unten verschoben werden</li><li><strong>Konfession</strong> soll nicht erscheinen</li><li>dafür soll das <strong>Alter</strong> ausgegeben werden</li></ul><h3 id="schriftgroße-und-schriftart-anpassen" tabindex="-1">Schriftgröße und Schriftart anpassen <a class="header-anchor" href="#schriftgroße-und-schriftart-anpassen" aria-label="Permalink to &quot;Schriftgröße und Schriftart anpassen&quot;">​</a></h3><p><a href="/bilder/reportdesigner/report-neu-und-veraendern-9.png"><img src="'+o+'" alt="Verändern von Text innerhalb von Textfeldern." loading="lazy"></a></p><p><em>Verändern von Text innerhalb von Textfeldern.</em></p><p>Im Modus <strong>Entwurf</strong> können Textfelder bearbeitet werden. Dazu wird ein Feld angeklickt. Nun erscheinen im oberen Werkzeugbereich Auswahlfelder für:</p><ul><li><strong>Schriftart</strong></li><li><strong>Schriftgröße</strong></li><li>Schriftstil (fett, kursiv, unterstrichen)</li><li>Ausrichtung innerhalb des Feldes</li></ul><p>Auch Datenbankfelder (<strong>DBText</strong>) besitzen diese Eigenschaften, da sie ebenfalls Text enthalten.</p>',15),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Sie können mehrere Felder gleichzeitig markieren. Ziehen Sie dazu mit gedrückter linker Maustaste einen Auswahlrahmen um die gewünschten Felder. Diese Auswahl wird auch "),e("strong",null,"Lasso"),n(" genannt. Markierte Felder erkennen Sie an den grauen Eckpunkten.")])],-1),r('<p>Auf diese Weise lassen sich Schriftart und Schriftstil aller betreffenden Felder in einem Schritt ändern.</p><p>Im Beispiel wird zusätzlich bei den Datenbankfeldern der Kursivstil deaktiviert (Schalter <strong>I</strong>).</p><h3 id="daten-hinzufugen-und-entfernen" tabindex="-1">Daten hinzufügen und entfernen <a class="header-anchor" href="#daten-hinzufugen-und-entfernen" aria-label="Permalink to &quot;Daten hinzufügen und entfernen&quot;">​</a></h3><p><a href="/bilder/reportdesigner/report-neu-und-veraendern-10.png"><img src="'+d+'" alt="Verschieben von Feldern – beachten Sie die blaue Hilfslinie." loading="lazy"></a></p><p><em>Verschieben von Feldern – beachten Sie die blaue Hilfslinie.</em></p><p>Nun wird das Feld <strong>Konfession</strong> entfernt. Dazu wird das Feld ausgewählt und mit <strong>Entf</strong> gelöscht (Label und Datenfeld).</p><p>Die nun entstehende Lücke wird genutzt, um das Datenfeld <strong>PLZ_Ort</strong> leicht nach unten zu verschieben.</p>',7),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Der Editor zeigt beim Ausrichten eine feine blaue Hilfslinie, wenn Feldkanten mit anderen Feldern übereinstimmen."),e("p",null,"So lassen sich Felder sehr präzise platzieren.")],-1),r('<p>Der darunterliegende Datenblock wird per Lasso markiert und nach oben geschoben, bis das Layout wieder geschlossen wirkt.</p><p><a href="/bilder/reportdesigner/report-neu-und-veraendern-11.png"><img src="'+p+'" alt="Einfügen eines neuen DB-Felds (»Alter«)." loading="lazy"></a></p><p><em>Einfügen eines neuen DB-Felds (»Alter«).</em></p><p>Nun soll das <strong>Alter</strong> ausgegeben werden. Dazu wird ein Feld vom Typ <strong>DBText</strong> im Report platziert. Wichtig: Es sollte nicht unmittelbar neben dem Geburtsdatum liegen, damit sich die Felder bei langen Angaben nicht überlappen.</p><p>Das neue Feld wird angepasst, im Beispiel auf <strong>Linksbündig</strong> gestellt.</p><p>Als <strong>Datenquelle</strong> wird <strong>Schueler</strong> gewählt. Das <strong>Datenfeld</strong> wird per Dropdown auf <strong>Alter</strong> gesetzt.</p><p><a href="/bilder/reportdesigner/report-neu-und-veraendern-12.png"><img src="'+u+'" alt="Der nun überarbeitete Report in der Vorschau." loading="lazy"></a></p><p><em>Der nun überarbeitete Report in der <strong>Vorschau</strong>.</em></p><p>In der <strong>Vorschau</strong> erscheint nun die angepasste Schulbescheinigung.</p><p>Ob das Ergebnis bereits zufriedenstellt oder weiter verfeinert werden soll, liegt im Ermessen des Anwenders.</p><p>Beispiele für mögliche Weiterentwicklungen:</p><ul><li>ein zusätzliches Textfeld mit der Beschriftung »Alter«</li><li>weitere Datenfelder (z. B. Erziehungsberechtigte)</li><li>Layout-Optimierung für gleichmäßige Abstände</li></ul><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Einen_vorhandenen_Report_anpassen" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6680.</p>',14)])])}const w=t(g,[["render",h]]);export{k as __pageData,w as default};
